const apiKey = $input.first().headers['x-api-key'];
if (!apiKey || apiKey !== $env.N8N_API_KEY) {
  throw new Error('Unauthorized');
}
const { brand_id } = $input.first().json.body;
if (!brand_id) throw new Error('Missing brand_id');

return [{
  json: {
    brand_id,
    log_id: 'wo-' + $now.toISO().replace(/[^0-9]/g, '').slice(0, 17),
    started_at: $now.toISO()
  }
}];

const brand = $('讀取品牌').first().json;
const analytics = $('讀取數據').all().map(i => i.json);
const posts = $('讀取貼文').all().map(i => i.json);

// 計算本週的開始日（上個週一）
const now = new Date();
const dayOfWeek = now.getDay();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
weekStart.setHours(0, 0, 0, 0);
const weekStartStr = weekStart.toISOString().split('T')[0];

// 篩選本週數據
const weekAnalytics = analytics.filter(a => {
  return a.collected_at >= weekStartStr;
});

// 按互動率排序
const sorted = weekAnalytics.sort((a, b) => 
  parseFloat(b.engagement_rate || '0') - parseFloat(a.engagement_rate || '0')
);

// 找出 top 3 貼文
const topPostIds = [...new Set(sorted.slice(0, 3).map(a => a.post_id))];
const topPosts = topPostIds.map(pid => {
  const post = posts.find(p => p.post_id === pid);
  const ana = sorted.find(a => a.post_id === pid);
  return {
    post_id: pid,
    caption: post?.caption?.slice(0, 100) || '',
    engagement_rate: ana?.engagement_rate || '0',
    likes: ana?.likes || '0',
    reach: ana?.reach || '0'
  };
});

// 計算整體統計
const totalReach = weekAnalytics.reduce((s, a) => s + parseInt(a.reach || '0'), 0);
const avgEngagement = weekAnalytics.length > 0 
  ? (weekAnalytics.reduce((s, a) => s + parseFloat(a.engagement_rate || '0'), 0) / weekAnalytics.length).toFixed(2)
  : '0';

const prompt = `你是社群媒體數據分析專家。請分析以下品牌的本週社群數據，並提供具體的優化建議。

品牌：${brand.brand_name}
主題：${brand.theme}
目標受眾：${brand.target_audience}

本週統計：
- 總觸及：${totalReach}
- 平均互動率：${avgEngagement}%
- 數據筆數：${weekAnalytics.length}

Top 3 表現最佳貼文：
${topPosts.map((p, i) => `${i+1}. 互動率 ${p.engagement_rate}% | 讚 ${p.likes} | 觸及 ${p.reach}\n   文案預覽：${p.caption}`).join('\n')}

請回傳 JSON 物件（不要 markdown 包裹），包含：
- top_topics: 表現最好的主題方向（字串）
- top_posts: 最佳貼文分析摘要（字串）
- caption_guidelines: 文案撰寫優化建議（字串，具體可執行的建議）
- image_guidelines: 圖片風格優化建議（字串）`;

return [{
  json: {
    prompt,
    week_start: weekStartStr,
    stats: { totalReach, avgEngagement, count: weekAnalytics.length },
    topPosts
  }
}];

