const brandId = $('驗證請求').first().json.brand_id;
const weekStart = $('準備分析').first().json.week_start;
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '{}';

let result;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  result = {
    top_topics: '解析失敗',
    top_posts: '解析失敗',
    caption_guidelines: content.slice(0, 500),
    image_guidelines: ''
  };
}

return [{
  json: {
    log_id: `opt-${Date.now()}`,
    brand_id: brandId,
    week_start: weekStart,
    top_topics: result.top_topics || '',
    top_posts: result.top_posts || '',
    caption_guidelines: result.caption_guidelines || '',
    image_guidelines: result.image_guidelines || '',
    created_at: new Date().toISOString()
  }
}];
